1	-- 集装箱残损检验与修理放行服务建表脚本（H2 MODE=MySQL，合成数据）
2	-- 时间口径：日期均为 UTC 自然日；金额单位为箱值同一货币单位，保留两位小数。
3	
4	create table if not exists iicl_code (
5	    code varchar(16) not null primary key,
6	    description varchar(128) not null
7	);
8	comment on table iicl_code is '合成 IICL 残损代码表（非真实 IICL 数据，仅本地演示）';
9	comment on column iicl_code.code is '残损代码，如 DN/BR/CT';
10	comment on column iicl_code.description is '残损代码中文说明';
11	
12	merge into iicl_code key(code) values
13	    ('DN', '凹痕'),
14	    ('BR', '弯曲变形'),
15	    ('CT', '割伤破口'),
16	    ('HO', '穿孔'),
17	    ('RS', '锈蚀'),
18	    ('PT', '涂层脱落'),
19	    ('CR', '裂纹'),
20	    ('MS', '构件缺失');
21	
22	create table if not exists damage_case (
23	    id bigint auto_increment primary key,
24	    container_no varchar(20) not null,
25	    container_value decimal(19,2) not null,
26	    status varchar(32) not null,
27	    determination varchar(16) null,
28	    rework_count int not null default 0,
29	    active_key varchar(20) null,
30	    created_at timestamp not null,
31	    updated_at timestamp not null,
32	    closed_at timestamp null
33	);
34	comment on table damage_case is '残损案主表；status 为流转状态，结案（RELEASED/TOTAL_LOSS）为终态';
35	comment on column damage_case.container_no is '箱号（合成数据）';
36	comment on column damage_case.container_value is '箱值，货币单位与修理费一致';
37	comment on column damage_case.status is 'REGISTERED/SURVEYED/ESTIMATED/APPROVED/REWORK/REPAIR_DONE/REPAIR_PASSED/TOTAL_LOSS_PENDING/RELEASED/TOTAL_LOSS';
38	comment on column damage_case.determination is '当前唯一判定：REPAIR 或 TOTAL_LOSS；全损与修理不并存，NULL 表示未估价';
39	comment on column damage_case.rework_count is '已返修次数，最多 1 次';
40	comment on column damage_case.active_key is '进行中案件的箱号唯一键；结案后置 NULL 以释放箱号';
41	comment on column damage_case.created_at is '创建时间（UTC）';
42	comment on column damage_case.updated_at is '最近更新时间（UTC）';
43	comment on column damage_case.closed_at is '结案时间（UTC），NULL 表示未结案';
44	
45	create unique index if not exists uk_damage_case_active on damage_case(active_key);
46	
47	create table if not exists damage_item (
48	    id bigint auto_increment primary key,
49	    case_id bigint not null,
50	    iicl_code varchar(16) not null,
51	    component varchar(64) not null,
52	    description varchar(256) null,
53	    responsibility varchar(16) not null,
54	    repair_cost decimal(19,2) not null
55	);
56	comment on table damage_item is '残损项清单，按合成 IICL 代码登记，可复算';
57	comment on column damage_item.case_id is '所属残损案 ID';
58	comment on column damage_item.iicl_code is '合成 IICL 残损代码，引用 iicl_code';
59	comment on column damage_item.component is '受损部位，如 侧板/箱门';
60	comment on column damage_item.description is '残损描述，NULL 表示未填写';
61	comment on column damage_item.responsibility is '责任方：OWNER 箱东 / TERMINAL 码头';
62	comment on column damage_item.repair_cost is '单项修理费，与箱值同货币单位';
63	
64	create table if not exists estimate (
65	    id bigint auto_increment primary key,
66	    case_id bigint not null,
67	    version int not null,
68	    total_cost decimal(19,2) not null,
69	    determination varchar(16) not null,
70	    status varchar(16) not null,
71	    request_id varchar(64) not null,
72	    created_at timestamp not null
73	);
74	comment on table estimate is '估价版本表，每次估价产生新版本，旧版本置 SUPERSEDED，全量保留可复算';
75	comment on column estimate.version is '估价版本号，按案件从 1 递增';
76	comment on column estimate.total_cost is '残损项修理费合计';
77	comment on column estimate.determination is '本版本判定：REPAIR/TOTAL_LOSS（单项修理费超箱值 30% 判全损，恰 30% 判修理）';
78	comment on column estimate.status is 'CURRENT 当前有效 / SUPERSEDED 已被新版本取代';
79	comment on column estimate.request_id is '产生本版本的幂等请求 ID';
80	
81	create table if not exists repair_approval (
82	    id bigint auto_increment primary key,
83	    case_id bigint not null,
84	    estimate_id bigint not null,
85	    approval_date date not null,
86	    status varchar(16) not null,
87	    created_at timestamp not null
88	);
89	comment on table repair_approval is '修理批复；有效期 7 个 UTC 自然日（批复日为第 1 日，恰第 7 日完工有效）';
90	comment on column repair_approval.estimate_id is '批复依据的估价版本 ID';
91	comment on column repair_approval.approval_date is '批复日期（UTC 自然日）';
92	comment on column repair_approval.status is 'ACTIVE 有效 / SUPERSEDED 因重新估价失效';
93	
94	create table if not exists repair_completion (
95	    id bigint auto_increment primary key,
96	    case_id bigint not null,
97	    completion_date date not null,
98	    rework boolean not null,
99	    created_at timestamp not null
100	);
101	comment on table repair_completion is '修理完工登记；rework=true 表示返修完工（仅允许一次返修）';
102	comment on column repair_completion.completion_date is '完工日期（UTC 自然日），须在批复有效期内';
103	
104	create table if not exists reinspection (
105	    id bigint auto_increment primary key,
106	    case_id bigint not null,
107	    passed boolean not null,
108	    created_at timestamp not null
109	);
110	comment on table reinspection is '复检记录；不合格允许返修一次，返修后仍不合格转全损评估';
111	comment on column reinspection.passed is 'true 合格 / false 不合格';
112	
113	create table if not exists idempotency_record (
114	    request_id varchar(64) not null primary key,
115	    endpoint varchar(64) not null,
116	    fingerprint varchar(64) not null,
117	    status varchar(16) not null,
118	    response_json clob null,
119	    created_at timestamp not null
120	);
121	comment on table idempotency_record is '幂等请求记录：同键同参返回首次结果，同键异参返回 409';
122	comment on column idempotency_record.request_id is '幂等请求 ID，全局唯一';
123	comment on column idempotency_record.endpoint is '请求入口标识，参与指纹计算';
124	comment on column idempotency_record.fingerprint is 'requestId 与全部业务字段的 SHA-256 指纹';
125	comment on column idempotency_record.status is 'IN_PROGRESS 处理中 / COMPLETED 已完成';
126	comment on column idempotency_record.response_json is '首次成功响应报文，用于同键重放';
127	
128	create table if not exists case_event (
129	    id bigint auto_increment primary key,
130	    case_id bigint not null,
131	    event_type varchar(32) not null,
132	    payload varchar(512) null,
133	    created_at timestamp not null
134	);
135	comment on table case_event is '案件事件流；结案后迟到检验照片仅记录 LATE_PHOTO 事件，不改变案件状态；QUALIFICATION_RISK 为批复后供应商资格撤销风险事件';
136	comment on column case_event.event_type is '事件类型：PHOTO 检验照片 / LATE_PHOTO 结案后迟到照片 / QUALIFICATION_RISK 批复后资格撤销风险';
137	comment on column case_event.payload is '事件负载（如照片引用或结构化 JSON），NULL 表示无';
138	
139	-- ======================================================================
140	-- 修箱批复前密封询价与比价（合成规则，仅本地演示，不用于生产）
141	-- 金额单位：正整数分；所有时刻均为 UTC 精确时刻（timestamp）。
142	-- ======================================================================
143	
144	create table if not exists repair_method (
145	    code varchar(16) not null primary key,
146	    description varchar(128) not null
147	);
148	comment on table repair_method is '合成修箱工法代码表（非真实数据，仅本地演示）';
149	comment on column repair_method.code is '工法代码，如 WELD/STRAIGHTEN/REPLACE/PATCH/PAINT';
150	comment on column repair_method.description is '工法中文说明';
