1	package com.example.starter.damage.service;
2	
3	import com.example.starter.damage.dto.InquiryRequests.CreateSupplierRequest;
4	import com.example.starter.damage.dto.InquiryRequests.OpenBidsRequest;
5	import com.example.starter.damage.dto.InquiryRequests.PublishInquiryRequest;
6	import com.example.starter.damage.dto.InquiryRequests.QualificationGrantRequest;
7	import com.example.starter.damage.dto.InquiryRequests.QualificationRevokeRequest;
8	import com.example.starter.damage.dto.InquiryRequests.ReviewRequest;
9	import com.example.starter.damage.dto.InquiryRequests.SubmitBidRequest;
10	import com.example.starter.damage.dto.InquiryViews.BidView;
11	import com.example.starter.damage.dto.InquiryViews.InquiryView;
12	import com.example.starter.damage.dto.InquiryViews.OpeningView;
13	import com.example.starter.damage.dto.InquiryViews.ReviewResultView;
14	import com.example.starter.damage.dto.InquiryViews.SupplierView;
15	import org.springframework.stereotype.Service;
16	
17	/**
18	 * 密封询价幂等门面：写操作均以 requestId 幂等，
19	 * 指纹结构化覆盖入口、版本、集合与精确时刻；同键同参重放首次冻结结果，异参 409、失败不占键。
20	 */
21	@Service
22	public class InquiryService {
23	
24	    private final InquiryTxService txService;
25	    private final IdempotencyExecutor idempotency;
26	
27	    public InquiryService(InquiryTxService txService, IdempotencyExecutor idempotency) {
28	        this.txService = txService;
29	        this.idempotency = idempotency;
30	    }
31	
32	    public SupplierView createSupplier(CreateSupplierRequest request) {
33	        return idempotency.execute("CREATE_SUPPLIER", request.requestId(), request, SupplierView.class,
34	                () -> txService.createSupplier(request));
35	    }
36	
37	    public SupplierView grantQualification(String supplierNo, QualificationGrantRequest request) {
38	        return idempotency.execute("GRANT_QUAL#" + supplierNo, request.requestId(), request, SupplierView.class,
39	                () -> txService.grantQualification(supplierNo, request));
40	    }
41	
42	    public SupplierView revokeQualification(String supplierNo, QualificationRevokeRequest request) {
43	        return idempotency.execute("REVOKE_QUAL#" + supplierNo, request.requestId(), request, SupplierView.class,
44	                () -> txService.revokeQualification(supplierNo, request));
