64	/**
65	 * 修箱批复前密封询价事务内服务。
66	 *
67	 * <p>核心规则：
68	 * <ul>
69	 *   <li>询价版本固定残损项集合与每项允许工法，并设 UTC 报价截止时刻；now&lt;截止方可投标，恰在截止拒绝。</li>
70	 *   <li>一供应商一询价仅一个当前报价，修订追加版本并保留历史；整版校验，任一不符整版拒绝。</li>
71	 *   <li>截止后开标冻结全部报价，按开标时刻供应商资格有效状态排除/入选（不采用提交时旧资格），
72	 *       有效报价取总价最低，同价按供应商编号升序；零有效报价不开批复。</li>
73	 *   <li>开标结果首次冻结，重复开标始终返回首次清单，不随后续资格变化重算。</li>
74	 *   <li>两名不同复核人齐后，中标报价转为原案修理批复，并冻结询价与报价；原全损判定仍适用。</li>
75	 *   <li>撤销资格追加新版本；与开标经供应商行锁串行保证一致；批复后撤销仅记风险事件，不改历史中标证据。</li>
76	 * </ul>
77	 */
78	@Service
79	public class InquiryTxService {
80	
81	    /** 开标清单中资格失效的排除原因 */
82	    private static final String REASON_REVOKED = "QUALIFICATION_REVOKED";
83	    private static final String REASON_EXPIRED = "QUALIFICATION_EXPIRED";
84	
85	    /** 批复后撤销资格的风险事件类型 */
86	    private static final String EVENT_QUALIFICATION_RISK = "QUALIFICATION_RISK";
87	
88	    private final SupplierRepository supplierRepository;
89	    private final InquiryRepository inquiryRepository;
90	    private final DamageCaseRepository caseRepository;
91	    private final DamageFlowRepository flowRepository;
92	    private final IdempotencyExecutor idempotency;
93	    private final ObjectMapper objectMapper;
94	    private final Clock clock;
95	
96	    public InquiryTxService(SupplierRepository supplierRepository,
97	                            InquiryRepository inquiryRepository,
98	                            DamageCaseRepository caseRepository,
99	                            DamageFlowRepository flowRepository,
100	                            IdempotencyExecutor idempotency,
101	                            ObjectMapper objectMapper,
102	                            Clock clock) {
103	        this.supplierRepository = supplierRepository;
104	        this.inquiryRepository = inquiryRepository;
105	        this.caseRepository = caseRepository;
106	        this.flowRepository = flowRepository;
107	        this.idempotency = idempotency;
108	        this.objectMapper = objectMapper;
109	        this.clock = clock;
110	    }
111	
112	    private Instant now() {
113	        return Instant.now(clock);
114	    }
115	
116	    // ============================ 供应商与资格 ============================
117	
118	    /** 创建合成供应商（含适用工法）；供应商编号唯一，未知工法 400 */
119	    @Transactional
120	    public SupplierView createSupplier(CreateSupplierRequest request) {
121	        for (String method : request.methods()) {
122	            if (!supplierRepository.methodExists(method)) {
123	                throw ApiException.badRequest("未知修箱工法代码: " + method);
124	            }
125	        }
126	        if (new LinkedHashSet<>(request.methods()).size() != request.methods().size()) {
127	            throw ApiException.badRequest("适用工法不得重复");
128	        }
129	        Instant now = now();
130	        long supplierId;
131	        try {
132	            supplierId = supplierRepository.insertSupplier(request.supplierNo(), request.name(), now);
133	        } catch (DuplicateKeyException e) {
134	            throw ApiException.conflict("供应商编号已存在: " + request.supplierNo());
135	        }
136	        for (String method : request.methods()) {
137	            supplierRepository.addMethod(supplierId, method);
138	        }
139	        SupplierView view = toSupplierView(requireSupplierById(supplierId));
140	        idempotency.completeInTransaction(request.requestId(), view);
141	        return view;
142	    }
143	
144	    /** 授予/续期有效资格版本；expectedVersion 为当前最新资格版本号，首次授予传 0 */
145	    @Transactional
146	    public SupplierView grantQualification(String supplierNo, QualificationGrantRequest request) {
147	        SupplierRow supplier = lockSupplierByNo(supplierNo);
148	        Optional<QualRow> latest = supplierRepository.findLatestQualification(supplier.id());
149	        int expected = requireExpectedQualVersion(latest, request.expectedVersion());
150	        if (request.validTo() != null && !request.validTo().isAfter(request.validFrom())) {
151	            throw ApiException.badRequest("资格失效时刻必须晚于生效时刻");
152	        }
153	        int newVersion = expected + 1;
154	        supplierRepository.insertQualification(supplier.id(), newVersion, QualificationStatus.ACTIVE,
155	                request.validFrom(), request.validTo(), request.requestId(), now());
156	        SupplierView view = toSupplierView(supplier);
157	        idempotency.completeInTransaction(request.requestId(), view);
158	        return view;
159	    }
160	
161	    /**
162	     * 撤销资格：追加 REVOKED 新版本（validFrom=validTo=撤销时刻）。
163	     * 若该供应商的中标已转批复，则仅在相应案件记录风险事件，历史开标/报价/资格快照不改写。
164	     */
165	    @Transactional
166	    public SupplierView revokeQualification(String supplierNo, QualificationRevokeRequest request) {
167	        SupplierRow supplier = lockSupplierByNo(supplierNo);
168	        Optional<QualRow> latest = supplierRepository.findLatestQualification(supplier.id());
169	        int expected = requireExpectedQualVersion(latest, request.expectedVersion());
170	        if (latest.isEmpty()) {
171	            throw ApiException.unprocessable("供应商尚无有效资格版本，无法撤销");
172	        }
173	        if (latest.get().status() == QualificationStatus.REVOKED) {
174	            throw ApiException.unprocessable("供应商资格已撤销，请勿重复撤销");
175	        }
176	        Instant revokedAt = request.revokedAt();
177	        int newVersion = expected + 1;
178	        supplierRepository.insertQualification(supplier.id(), newVersion, QualificationStatus.REVOKED,
179	                revokedAt, revokedAt, request.requestId(), now());
180	
181	        // 已转批复的中标：仅追加风险事件，冻结证据不回写
182	        for (ConvertedWinRow win : inquiryRepository.listConvertedWinsForSupplier(supplier.id())) {
183	            flowRepository.insertEvent(win.caseId(), EVENT_QUALIFICATION_RISK,
184	                    buildRiskPayload(supplier.supplierNo(), win, newVersion, revokedAt), LocalDateTime.now(clock));
185	        }
186	
187	        SupplierView view = toSupplierView(supplier);
188	        idempotency.completeInTransaction(request.requestId(), view);
189	        return view;
190	    }
191	
192	    private int requireExpectedQualVersion(Optional<QualRow> latest, int expectedVersion) {
193	        int current = latest.map(QualRow::version).orElse(0);
194	        if (expectedVersion != current) {
195	            throw ApiException.conflict("资格版本已变化，期望版本 " + expectedVersion + " 与当前版本 " + current + " 不一致");
196	        }
197	        return current;
198	    }
199	
200	    private SupplierRow lockSupplierByNo(String supplierNo) {
201	        SupplierRow supplier = supplierRepository.findByNo(supplierNo)
202	                .orElseThrow(() -> ApiException.notFound("供应商不存在: " + supplierNo));
203	        return supplierRepository.findByIdForUpdate(supplier.id())
204	                .orElseThrow(() -> ApiException.notFound("供应商不存在: " + supplierNo));
205	    }
206	
207	    private SupplierRow requireSupplierById(long supplierId) {
208	        return supplierRepository.findById(supplierId)
209	                .orElseThrow(() -> ApiException.notFound("供应商不存在: " + supplierId));
210	    }
211	
212	    // ============================ 发布询价 ============================
213	
214	    /** 对“待批复”（已估价且判定修理）残损案发布密封询价版本 */
215	    @Transactional
216	    public InquiryView publishInquiry(long caseId, PublishInquiryRequest request) {
217	        CaseRow caseRow = caseRepository.findByIdForUpdate(caseId)
218	                .orElseThrow(() -> ApiException.notFound("残损案不存在: " + caseId));
219	        if (caseRow.status() != CaseStatus.ESTIMATED || caseRow.determination() != Determination.REPAIR) {
220	            throw ApiException.unprocessable("仅已估价且判定修理的待批复残损案可发布询价，当前状态: "
221	                    + caseRow.status() + "，判定: " + caseRow.determination());
222	        }
223	        EstimateView currentEstimate = flowRepository.findCurrentEstimate(caseId);
224	        if (currentEstimate == null) {
225	            throw ApiException.unprocessable("无有效估价版本，无法发布询价");
226	        }
227	        if (!request.deadline().isAfter(now())) {
228	            throw ApiException.unprocessable("报价截止时刻必须晚于当前时刻");
229	        }
230	
231	        int maxSeq = inquiryRepository.maxSeq(caseId);
232	        if (request.expectedVersion() != maxSeq) {
233	            throw ApiException.conflict("询价版本已变化，期望序号 " + request.expectedVersion()
234	                    + " 与当前序号数 " + maxSeq + " 不一致");
235	        }
236	        Optional<InquiryRow> latestInquiry = inquiryRepository.findLatestInquiryByCase(caseId);
237	        if (latestInquiry.isPresent() && latestInquiry.get().status() != InquiryStatus.NO_AWARD) {
238	            throw ApiException.unprocessable("当前询价版本尚未结束（状态 " + latestInquiry.get().status()
239	                    + "），不能发布新版本");
240	        }
241	
242	        // 固定残损项集合：请求必须与案件残损项一一对应
243	        List<DamageItemView> caseItems = flowRepository.listItems(caseId);
244	        Map<Long, DamageItemView> caseItemMap = caseItems.stream()
245	                .collect(Collectors.toMap(DamageItemView::id, v -> v, (a, b) -> a, LinkedHashMap::new));
246	        if (request.items().size() != caseItemMap.size()) {
247	            throw ApiException.badRequest("询价残损项数量必须与案件残损项一致: 需 " + caseItemMap.size()
248	                    + " 项，实供 " + request.items().size() + " 项");
249	        }
250	        Set<Long> covered = new LinkedHashSet<>();
251	        for (InquiryItemSpec spec : request.items()) {
252	            if (!caseItemMap.containsKey(spec.damageItemId())) {
253	                throw ApiException.badRequest("询价残损项不属于该案件或不存在: " + spec.damageItemId());
254	            }
255	            if (!covered.add(spec.damageItemId())) {
256	                throw ApiException.badRequest("询价残损项不得重复: " + spec.damageItemId());
257	            }
258	            if (new LinkedHashSet<>(spec.methods()).size() != spec.methods().size()) {
259	                throw ApiException.badRequest("残损项允许工法不得重复: " + spec.damageItemId());
260	            }
261	            for (String method : spec.methods()) {
262	                if (!supplierRepository.methodExists(method)) {
263	                    throw ApiException.badRequest("未知修箱工法代码: " + method);
264	                }
265	            }
266	        }
267	
268	        int seq = maxSeq + 1;
269	        long inquiryId = inquiryRepository.insertInquiry(caseId, seq, request.deadline(),
270	                request.requestId(), now());
271	        int lineNo = 1;
272	        for (InquiryItemSpec spec : request.items()) {
273	            long inquiryItemId = inquiryRepository.insertInquiryItem(inquiryId, lineNo, spec.damageItemId());
274	            for (String method : spec.methods()) {
275	                inquiryRepository.addInquiryItemMethod(inquiryItemId, method);
276	            }
277	            lineNo++;
278	        }
279	
280	        InquiryView view = toInquiryView(requireInquiry(inquiryId));
281	        idempotency.completeInTransaction(request.requestId(), view);
282	        return view;
283	    }
284	
285	    // ============================ 报价 ============================
286	
287	    /** 提交/修订整版报价；整版校验，任一不符整版拒绝（不保留任何半截版本） */
288	    @Transactional
289	    public BidView submitBid(long inquiryId, String supplierNo, SubmitBidRequest request) {
290	        InquiryRow inquiry = inquiryRepository.findInquiryByIdForUpdate(inquiryId)
291	                .orElseThrow(() -> ApiException.notFound("询价版本不存在: " + inquiryId));
292	        if (inquiry.status() != InquiryStatus.OPEN) {
293	            throw ApiException.unprocessable("询价当前状态不允许报价: " + inquiry.status());
294	        }
295	        Instant now = now();
296	        if (!now.isBefore(inquiry.deadline())) {
297	            throw ApiException.unprocessable("已到或已过报价截止时刻（UTC " + inquiry.deadline() + "），拒绝投标");
298	        }
299	        SupplierRow supplier = supplierRepository.findByNo(supplierNo)
300	                .orElseThrow(() -> ApiException.notFound("供应商不存在: " + supplierNo));
301	        Set<String> supplierMethods = new LinkedHashSet<>(supplierRepository.listMethods(supplier.id()));
302	
303	        List<InquiryItemRow> inquiryItems = inquiryRepository.listInquiryItems(inquiryId);
304	        Map<Integer, InquiryItemRow> byLine = inquiryItems.stream()
305	                .collect(Collectors.toMap(InquiryItemRow::lineNo, r -> r));
306	        Map<Integer, BidLineInput> inputByLine = new LinkedHashMap<>();
307	        for (BidLineInput line : request.lines()) {
308	            if (inputByLine.put(line.lineNo(), line) != null) {
309	                throw ApiException.unprocessable("报价行号重复: " + line.lineNo());
310	            }
311	        }
312	        if (inputByLine.size() != inquiryItems.size()) {
313	            throw ApiException.unprocessable("报价必须覆盖全部 " + inquiryItems.size()
314	                    + " 个残损项，实供 " + inputByLine.size() + " 行，整版拒绝");
315	        }
316	
317	        // 先整版校验全部通过后再落库，保证“整版拒绝”
318	        List<ValidatedLine> validated = new ArrayList<>();
319	        long total = 0;
320	        for (InquiryItemRow item : inquiryItems) {
321	            BidLineInput input = inputByLine.get(item.lineNo());
322	            if (input == null) {
323	                throw ApiException.unprocessable("报价缺少残损项行: " + item.lineNo() + "，整版拒绝");
324	            }
325	            List<String> allowed = inquiryRepository.listInquiryItemMethods(item.id());
326	            if (!allowed.contains(input.methodCode())) {
327	                throw ApiException.unprocessable("第 " + item.lineNo() + " 行工法 " + input.methodCode()
328	                        + " 不在询价允许工法内，整版拒绝");
329	            }
330	            if (!supplierMethods.contains(input.methodCode())) {
331	                throw ApiException.unprocessable("第 " + item.lineNo() + " 行工法 " + input.methodCode()
332	                        + " 不在供应商适用工法内，整版拒绝");
333	            }
334	            if (input.amountCents() <= 0) {
335	                throw ApiException.badRequest("报价金额必须为正整数分");
336	            }
337	            validated.add(new ValidatedLine(item, input.methodCode(), input.amountCents()));
338	            total += input.amountCents();
339	        }
340	
341	        BidRow bid = inquiryRepository.findBidForUpdate(inquiryId, supplier.id()).orElse(null);
342	        int currentVersion;
343	        if (bid == null) {
344	            if (request.expectedVersion() != 0) {
345	                throw ApiException.conflict("报价版本不存在，首次报价期望版本必须为 0");
346	            }
347	            try {
348	                long bidId = inquiryRepository.insertBid(inquiryId, supplier.id(), now);
349	                bid = inquiryRepository.findBidForUpdate(inquiryId, supplier.id())
350	                        .orElseThrow(() -> new IllegalStateException("报价落库失败"));
351	            } catch (DuplicateKeyException e) {
352	                // 并发首次报价由 (inquiry_id, supplier_id) 唯一索引仲裁
353	                throw ApiException.conflict("该供应商的报价已被并发创建，请基于当前报价版本修订");
354	            }
355	            currentVersion = 0;
356	        } else {
357	            if (bid.status().equals("FROZEN")) {
358	                throw ApiException.unprocessable("报价已随开标冻结，不得修订");
359	            }
360	            currentVersion = bid.currentVersion();
361	            if (request.expectedVersion() != currentVersion) {
362	                throw ApiException.conflict("报价版本已变化，期望版本 " + request.expectedVersion()
363	                        + " 与当前版本 " + currentVersion + " 不一致");
364	            }
365	        }
366	
367	        int newVersion = currentVersion + 1;
368	        inquiryRepository.supersedeBidVersions(bid.id());
369	        long bidVersionId = inquiryRepository.insertBidVersion(bid.id(), newVersion, total,
370	                request.requestId(), now);
371	        for (ValidatedLine line : validated) {
372	            inquiryRepository.insertBidLine(bidVersionId, line.item.id(), line.item.lineNo(),
373	                    line.methodCode, line.amountCents);
374	        }
375	        int updated = inquiryRepository.compareAndSetBidVersion(bid.id(), currentVersion, newVersion, now);
376	        if (updated == 0) {
377	            throw ApiException.conflict("报价并发修订冲突，报价已被冻结或更新，请重试");
378	        }
379	
380	        BidView view = toBidView(inquiryId, supplier.id());
381	        idempotency.completeInTransaction(request.requestId(), view);
382	        return view;
383	    }
384	
385	    private record ValidatedLine(InquiryItemRow item, String methodCode, long amountCents) {
386	    }
387	
388	    // ============================ 开标比价 ============================
389	
390	    /** 截止后开标：冻结全部报价并按开标时刻资格比价；重复开标返回首次冻结清单 */
391	    @Transactional
392	    public OpeningView openBids(long inquiryId, OpenBidsRequest request) {
393	        InquiryRow inquiry = inquiryRepository.findInquiryByIdForUpdate(inquiryId)
394	                .orElseThrow(() -> ApiException.notFound("询价版本不存在: " + inquiryId));
395	
396	        // 业务级幂等：无论是否同一 requestId，重复开标一律返回首次冻结清单，不重算
397	        Optional<OpeningRow> existing = inquiryRepository.findOpeningByInquiryForUpdate(inquiryId);
398	        if (existing.isPresent()) {
399	            OpeningView frozen = toOpeningView(inquiry, existing.get());
400	            //重复开标即便使用新 requestId 也须写入其幂等完成标记，避免键滞留处理中
401	            idempotency.completeInTransaction(request.requestId(), frozen);
402	            return frozen;
403	        }
404	
405	        if (inquiry.status() != InquiryStatus.OPEN) {
406	            throw ApiException.unprocessable("询价当前状态不允许开标: " + inquiry.status());
407	        }
408	        Instant openedAt = now();
409	        if (openedAt.isBefore(inquiry.deadline())) {
410	            throw ApiException.unprocessable("未到报价截止时刻，不能开标");
411	        }
412	        if (request.expectedVersion() != inquiry.version()) {
413	            throw ApiException.conflict("询价版本已变化，期望版本 " + request.expectedVersion()
414	                    + " 与当前版本 " + inquiry.version() + " 不一致");
415	        }
416	
417	        // 冻结全部报价（冻结后不得修订）
418	        inquiryRepository.freezeBids(inquiryId);
419	
420	        List<BidRow> bids = inquiryRepository.listBids(inquiryId);
421	        List<Candidate> candidates = new ArrayList<>();
422	        for (BidRow bid : bids) {
423	            // 与撤销竞争：先锁供应商行再读资格版本，开标/撤销在此串行
424	            SupplierRow supplier = supplierRepository.findByIdForUpdate(bid.supplierId())
425	                    .orElseGet(() -> requireSupplierById(bid.supplierId()));
426	            QualRow qual = supplierRepository.findLatestQualificationForUpdate(supplier.id()).orElse(null);
427	            BidVersionRow currentVersion = inquiryRepository.listBidVersions(bid.id()).stream()
428	                    .filter(v -> v.status().equals("CURRENT"))
429	                    .findFirst().orElseThrow();
430	
431	            boolean valid;
432	            String reason = null;
433	            if (qual == null) {
434	                valid = false;
435	                reason = REASON_EXPIRED;
436	            } else if (qual.status() == QualificationStatus.REVOKED) {
437	                valid = false;
438	                reason = REASON_REVOKED;
439	            } else if (!covers(qual, openedAt)) {
440	                valid = false;
441	                reason = REASON_EXPIRED;
442	            } else {
443	                valid = true;
444	            }
445	            candidates.add(new Candidate(supplier, qual, currentVersion, valid, reason));
446	        }
447	
448	        // 有效报价排序：总价升序，同价按供应商编号升序
449	        List<Candidate> ranked = candidates.stream()
450	                .filter(c -> c.valid)
451	                .sorted(Comparator.comparingLong((Candidate c) -> c.version.totalCents())
452	                        .thenComparing(c -> c.supplier.supplierNo()))
453	                .toList();
454	
455	        boolean awarded = !ranked.isEmpty();
456	        Candidate winner = awarded ? ranked.get(0) : null;
457	        String openingStatus = awarded ? "AWARDED" : "NO_VALID";
458	
459	        long openingId = inquiryRepository.insertOpening(inquiryId, inquiry.version(), openedAt, openingStatus,
460	                winner == null ? null : winner.supplier.id(),
461	                winner == null ? null : winner.version.id(),
462	                winner == null ? null : winner.version.totalCents(),
463	                request.requestId());
464	        OpeningRow opening = inquiryRepository.findOpeningByIdForUpdate(openingId).orElseThrow();
465	
466	        Map<Long, Integer> rankBySupplier = new LinkedHashMap<>();
467	        for (int i = 0; i < ranked.size(); i++) {
468	            rankBySupplier.put(ranked.get(i).supplier.id(), i + 1);
469	        }
470	        for (Candidate c : candidates) {
471	            inquiryRepository.insertOpeningEntry(openingId, c.supplier.id(), c.version.id(),
472	                    c.version.totalCents(),
473	                    c.qual == null ? 0 : c.qual.version(),
474	                    c.qual == null ? QualificationStatus.REVOKED.name() : c.qual.status().name(),
475	                    c.qual == null ? openedAt : c.qual.validFrom(),
476	                    c.qual == null ? openedAt : c.qual.validTo(),
477	                    c.valid, c.reason, rankBySupplier.get(c.supplier.id()));
478	        }
479	
480	        InquiryStatus newInquiryStatus = awarded ? InquiryStatus.OPENED : InquiryStatus.NO_AWARD;
481	        int updated = inquiryRepository.compareAndSetInquiry(inquiryId, inquiry.version(),
482	                newInquiryStatus, inquiry.version() + 1);
483	        if (updated == 0) {
484	            throw ApiException.conflict("开标并发冲突，询价版本已变化，请重试");
485	        }
486	
487	        OpeningView view = toOpeningView(inquiryRepository.findInquiryById(inquiryId).orElseThrow(), opening);
488	        idempotency.completeInTransaction(request.requestId(), view);
489	        return view;
490	    }
491	
492	    /** 资格版本是否覆盖指定时刻：ACTIVE 且 validFrom &lt;= t &lt; validTo（validTo 为空表示长期有效） */
493	    private boolean covers(QualRow qual, Instant t) {
494	        if (qual.status() != QualificationStatus.ACTIVE) {
495	            return false;
496	        }
497	        if (t.isBefore(qual.validFrom())) {
498	            return false;
499	        }
500	        return qual.validTo() == null || t.isBefore(qual.validTo());
501	    }
502	
503	    private record Candidate(SupplierRow supplier, QualRow qual, BidVersionRow version, boolean valid, String reason) {
504	    }
505	
506	    // ============================ 双重复核与转批复 ============================
507	
508	    /** 复核中标报价；两名不同复核人齐后将中标报价转为原案修理批复 */
509	    @Transactional
510	    public ReviewResultView review(long inquiryId, ReviewRequest request) {
511	        InquiryRow inquiry = inquiryRepository.findInquiryByIdForUpdate(inquiryId)
512	                .orElseThrow(() -> ApiException.notFound("询价版本不存在: " + inquiryId));
513	        OpeningRow opening = inquiryRepository.findOpeningByInquiryForUpdate(inquiryId)
514	                .orElseThrow(() -> ApiException.unprocessable("询价尚未开标，无法复核"));
515	        if ("NO_VALID".equals(opening.status())) {
516	            throw ApiException.unprocessable("开标零有效报价，不开批复");
517	        }
518	        if (inquiry.status() == InquiryStatus.CONVERTED) {
519	            throw ApiException.unprocessable("中标报价已转批复，询价与报价已冻结，不能再复核");
520	        }
521	        if (inquiry.status() != InquiryStatus.OPENED) {
522	            throw ApiException.unprocessable("询价当前状态不允许复核: " + inquiry.status());
523	        }
524	
525	        List<String> reviewers = inquiryRepository.listReviews(opening.id()).stream()
526	                .map(r -> r.reviewer()).distinct().toList();
527	        if (reviewers.contains(request.reviewer())) {
528	            throw ApiException.unprocessable("同一复核人不得重复复核: " + request.reviewer());
529	        }
530	        try {
531	            inquiryRepository.insertReview(inquiryId, opening.id(), request.reviewer(),
532	                    request.requestId(), now());
533	        } catch (DuplicateKeyException e) {
534	            throw ApiException.unprocessable("同一复核人不得重复复核: " + request.reviewer());
535	        }
536	
537	        List<String> updatedReviewers = inquiryRepository.listReviews(opening.id()).stream()
538	                .map(r -> r.reviewer()).distinct().toList();
539	
540	        LocalDate approvalDate = null;
541	        Long approvalId = null;
542	        boolean converted = false;
543	        if (updatedReviewers.size() >= 2) {
544	            // 两名不同复核人齐：将中标报价转为原案修理批复
545	            long caseId = inquiry.caseId();
546	            CaseRow caseRow = caseRepository.findByIdForUpdate(caseId)
547	                    .orElseThrow(() -> ApiException.notFound("残损案不存在: " + caseId));
548	            if (caseRow.status() != CaseStatus.ESTIMATED || caseRow.determination() != Determination.REPAIR) {
549	                throw ApiException.unprocessable("原案已不满足修理批复条件（状态 " + caseRow.status()
550	                        + "，判定 " + caseRow.determination() + "），全损判定仍适用，转批复拒绝");
551	            }
552	            EstimateView estimate = flowRepository.findCurrentEstimate(caseId);
553	            if (estimate == null) {
554	                throw ApiException.unprocessable("无有效估价版本，无法转批复");
555	            }
556	            approvalDate = LocalDate.now(clock);
557	            approvalId = flowRepository.insertApproval(caseId, estimate.id(), approvalDate,
558	                    "INQUIRY", opening.id(), java.time.LocalDateTime.now(clock));
559	            caseRepository.updateState(caseId, CaseStatus.APPROVED, Determination.REPAIR,
560	                    java.time.LocalDateTime.now(clock));
561	            int updated = inquiryRepository.compareAndSetInquiry(inquiryId, inquiry.version(),
562	                    InquiryStatus.CONVERTED, inquiry.version() + 1);
563	            if (updated == 0) {
564	                throw ApiException.conflict("转批复并发冲突，询价版本已变化，请重试");
565	            }
566	            converted = true;
567	        }
568	
569	        InquiryRow refreshed = inquiryRepository.findInquiryById(inquiryId).orElseThrow();
570	        OpeningRow refreshedOpening = inquiryRepository.findOpeningByInquiry(inquiryId).orElseThrow();
571	        OpeningView openingView = toOpeningView(refreshed, refreshedOpening, updatedReviewers, converted, approvalId);
572	        ReviewResultView view = new ReviewResultView(openingView, approvalDate);
573	        idempotency.completeInTransaction(request.requestId(), view);
574	        return view;
575	    }
576	
577	    // ============================ 查询 ============================
578	
579	    @Transactional(readOnly = true)
580	    public SupplierView getSupplier(String supplierNo) {
581	        SupplierRow supplier = supplierRepository.findByNo(supplierNo)
582	                .orElseThrow(() -> ApiException.notFound("供应商不存在: " + supplierNo));
583	        return toSupplierView(supplier);
584	    }
585	
586	    @Transactional(readOnly = true)
587	    public InquiryView getInquiry(long inquiryId) {
588	        return toInquiryView(requireInquiry(inquiryId));
589	    }
590	
591	    @Transactional(readOnly = true)
592	    public BidView getBid(long inquiryId, String supplierNo) {
593	        InquiryRow inquiry = inquiryRepository.findInquiryById(inquiryId)
594	                .orElseThrow(() -> ApiException.notFound("询价版本不存在: " + inquiryId));
595	        SupplierRow supplier = supplierRepository.findByNo(supplierNo)
596	                .orElseThrow(() -> ApiException.notFound("供应商不存在: " + supplierNo));
597	        BidRow bid = inquiryRepository.findBid(inquiryId, supplier.id())
598	                .orElseThrow(() -> ApiException.notFound("该供应商尚未对本询价报价"));
599	        return toBidView(inquiry.id(), supplier.id());
600	    }
601	
602	    @Transactional(readOnly = true)
603	    public OpeningView getOpening(long inquiryId) {
604	        InquiryRow inquiry = inquiryRepository.findInquiryById(inquiryId)
605	                .orElseThrow(() -> ApiException.notFound("询价版本不存在: " + inquiryId));
606	        OpeningRow opening = inquiryRepository.findOpeningByInquiry(inquiryId)
607	                .orElseThrow(() -> ApiException.notFound("询价尚未开标，无开标清单"));
608	        return toOpeningView(inquiry, opening);
609	    }
610	
611	    // ============================ 视图装配 ============================
612	
613	    private InquiryRow requireInquiry(long inquiryId) {
614	        return inquiryRepository.findInquiryById(inquiryId)
615	                .orElseThrow(() -> ApiException.notFound("询价版本不存在: " + inquiryId));
616	    }
617	
618	    private SupplierView toSupplierView(SupplierRow supplier) {
619	        List<String> methods = supplierRepository.listMethods(supplier.id());
620	        Optional<QualRow> latest = supplierRepository.findLatestQualification(supplier.id());
621	        QualificationView qualView = latest.map(q -> new QualificationView(
622	                q.id(), q.version(), q.status(), q.validFrom(), q.validTo())).orElse(null);
623	        return new SupplierView(supplier.id(), supplier.supplierNo(), supplier.name(),
624	                methods, qualView, latest.map(QualRow::version).orElse(0));
625	    }
626	
627	    private InquiryView toInquiryView(InquiryRow inquiry) {
628	        Map<Long, DamageItemView> caseItems = flowRepository.listItems(inquiry.caseId()).stream()
629	                .collect(Collectors.toMap(DamageItemView::id, v -> v));
630	        List<InquiryItemView> itemViews = new ArrayList<>();
631	        for (InquiryItemRow row : inquiryRepository.listInquiryItems(inquiry.id())) {
632	            DamageItemView damage = caseItems.get(row.damageItemId());
633	            itemViews.add(new InquiryItemView(row.lineNo(), row.damageItemId(),
634	                    damage == null ? null : damage.iiclCode(),
635	                    damage == null ? null : damage.component(),
636	                    inquiryRepository.listInquiryItemMethods(row.id())));
637	        }
638	        return new InquiryView(inquiry.id(), inquiry.caseId(), inquiry.seq(), inquiry.version(),
639	                inquiry.deadline(), inquiry.status(), itemViews);
640	    }
641	
642	    private BidView toBidView(long inquiryId, long supplierId) {
643	        BidRow bid = inquiryRepository.findBid(inquiryId, supplierId).orElseThrow();
644	        List<BidVersionView> history = new ArrayList<>();
645	        for (BidVersionRow v : inquiryRepository.listBidVersions(bid.id())) {
646	            List<BidLineView> lines = inquiryRepository.listBidLines(v.id()).stream()
647	                    .map(l -> new BidLineView(l.lineNo(), l.methodCode(), l.amountCents()))
648	                    .toList();
649	            history.add(new BidVersionView(v.id(), v.version(), v.totalCents(), v.status(), lines));
650	        }
651	        return new BidView(bid.id(), inquiryId, supplierId, bid.currentVersion(), bid.status(), history);
652	    }
653	
654	    private OpeningView toOpeningView(InquiryRow inquiry, OpeningRow opening) {
655	        List<String> reviewers = inquiryRepository.listReviews(opening.id()).stream()
656	                .map(r -> r.reviewer()).toList();
657	        boolean converted = inquiry.status() == InquiryStatus.CONVERTED;
658	        ApprovalView approval = flowRepository.findApprovalByOpeningId(opening.id());
659	        return toOpeningView(inquiry, opening, reviewers, converted, approval == null ? null : approval.id());
660	    }
661	
662	    private OpeningView toOpeningView(InquiryRow inquiry, OpeningRow opening, List<String> reviewers,
663	                                      boolean converted, Long approvalId) {
664	        List<OpeningEntryView> entries = new ArrayList<>();
665	        for (OpeningEntryRow e : inquiryRepository.listOpeningEntries(opening.id())) {
666	            SupplierRow supplier = supplierRepository.findById(e.supplierId()).orElse(null);
667	            int bidVersionNo = inquiryRepository.findBidVersionById(e.bidVersionId())
668	                    .map(BidVersionRow::version).orElse(0);
669	            entries.add(new OpeningEntryView(
670	                    e.supplierId(),
671	                    supplier == null ? null : supplier.supplierNo(),
672	                    e.bidVersionId(),
673	                    bidVersionNo,
674	                    e.totalCents(),
675	                    e.qualificationVersion(),
676	                    QualificationStatus.valueOf(e.qualificationStatus()),
677	                    e.qualValidFrom(),
678	                    e.qualValidTo(),
679	                    e.valid(),
680	                    e.excludeReason(),
681	                    e.rankNo()));
682	        }
683	        String winnerNo = null;
684	        if (opening.winnerSupplierId() != null) {
685	            winnerNo = supplierRepository.findById(opening.winnerSupplierId())
686	                    .map(SupplierRow::supplierNo).orElse(null);
687	        }
688	        return new OpeningView(opening.id(), inquiry.id(), opening.inquiryVersion(), opening.openedAt(),
689	                opening.status(), opening.winnerSupplierId(), winnerNo,
690	                opening.winnerBidVersionId(), opening.winnerTotalCents(),
691	                reviewers, converted, approvalId, entries);
692	    }
693	
694	    private String buildRiskPayload(String supplierNo, ConvertedWinRow win, int qualificationVersion,
695	                                    Instant revokedAt) {
696	        try {
697	            return objectMapper.writeValueAsString(Map.of(
698	                    "supplierNo", supplierNo,
699	                    "inquiryId", win.inquiryId(),
700	                    "openingId", win.openingId(),
701	                    "qualificationVersion", qualificationVersion,
702	                    "revokedAt", revokedAt.toString()));
703	        } catch (Exception e) {
704	            throw new IllegalStateException("风险事件负载序列化失败", e);
705	        }
706	    }
707	}
