1	package com.example.starter.damage.service;
2	
3	import com.example.starter.damage.api.ApiException;
4	import com.example.starter.damage.domain.CaseStatus;
5	import com.example.starter.damage.domain.Determination;
6	import com.example.starter.damage.dto.Requests.ApprovalRequest;
7	import com.example.starter.damage.dto.Requests.CloseRequest;
8	import com.example.starter.damage.dto.Requests.CompletionRequest;
9	import com.example.starter.damage.dto.Requests.EstimateRequest;
10	import com.example.starter.damage.dto.Requests.PhotoRequest;
11	import com.example.starter.damage.dto.Requests.RegisterRequest;
12	import com.example.starter.damage.dto.Requests.ReinspectionRequest;
13	import com.example.starter.damage.dto.Requests.SurveyRequest;
14	import com.example.starter.damage.dto.Views.ApprovalView;
15	import com.example.starter.damage.dto.Views.CaseDetailView;
16	import com.example.starter.damage.dto.Views.CaseView;
17	import com.example.starter.damage.dto.Views.CompletionView;
18	import com.example.starter.damage.dto.Views.EstimateView;
19	import com.example.starter.damage.dto.Views.PhotoResult;
20	import com.example.starter.damage.store.DamageCaseRepository;
21	import com.example.starter.damage.store.DamageCaseRepository.CaseRow;
22	import com.example.starter.damage.store.DamageFlowRepository;
23	import com.example.starter.damage.store.InquiryRepository;
24	import org.springframework.dao.DuplicateKeyException;
25	import org.springframework.stereotype.Service;
26	import org.springframework.transaction.annotation.Transactional;
27	
28	import java.math.BigDecimal;
29	import java.time.Clock;
30	import java.time.LocalDate;
31	import java.time.LocalDateTime;
32	import java.util.EnumSet;
33	import java.util.Set;
34	
35	/**
36	 * 残损案事务内业务服务：状态机流转、30% 全损阈值、批复 7 个 UTC 自然日有效期、
37	 * 返修一次限制与判定唯一性均在此强制。所有写方法在事务内执行。
38	 */
39	@Service
40	public class DamageCaseTxService {
41	
42	    /** 全损阈值：单项修理费超过箱值 30% 判全损，恰 30% 按修理处理 */
43	    static final BigDecimal TOTAL_LOSS_THRESHOLD = new BigDecimal("0.30");
44	
45	    /** 修理批复有效期：7 个 UTC 自然日，批复日为第 1 日，恰第 7 日完工有效 */
46	    static final long APPROVAL_VALID_DAYS = 7;
47	
48	    private static final Set<CaseStatus> TERMINAL = EnumSet.of(CaseStatus.RELEASED, CaseStatus.TOTAL_LOSS);
49	
50	    private final DamageCaseRepository caseRepository;
51	    private final DamageFlowRepository flowRepository;
52	    private final InquiryRepository inquiryRepository;
53	    private final IdempotencyExecutor idempotency;
54	    private final Clock clock;
55	
56	    public DamageCaseTxService(DamageCaseRepository caseRepository,
57	                               DamageFlowRepository flowRepository,
58	                               InquiryRepository inquiryRepository,
59	                               IdempotencyExecutor idempotency,
60	                               Clock clock) {
61	        this.caseRepository = caseRepository;
62	        this.flowRepository = flowRepository;
63	        this.inquiryRepository = inquiryRepository;
64	        this.idempotency = idempotency;
65	        this.clock = clock;
66	    }
67	
68	    /** 到港登记：同一箱号同时刻只允许一个进行中残损案，由 active_key 唯一索引仲裁 */
69	    @Transactional
70	    public CaseView register(RegisterRequest request) {
71	        LocalDateTime now = LocalDateTime.now(clock);
72	        long caseId;
73	        try {
74	            caseId = caseRepository.insert(request.containerNo(), request.containerValue(), now);
75	        } catch (DuplicateKeyException e) {
76	            throw ApiException.conflict("同一箱号已存在进行中的残损案，仅唯一受理");
77	        }
78	        CaseView view = loadCase(caseId).toView();
79	        idempotency.completeInTransaction(request.requestId(), view);
80	        return view;
81	    }
82	
83	    /** 检验：按合成 IICL 代码登记残损项并区分责任方，仅在 REGISTERED 状态可登记 */
84	    @Transactional
85	    public CaseDetailView survey(long caseId, SurveyRequest request) {
86	        CaseRow row = lockCase(caseId);
87	        requireStatus(row, CaseStatus.REGISTERED, "仅到港登记状态可登记检验残损项");
88	        for (var item : request.items()) {
89	            if (!flowRepository.iiclCodeExists(item.iiclCode())) {
90	                throw ApiException.badRequest("未知 IICL 残损代码: " + item.iiclCode());
91	            }
92	            flowRepository.insertItem(caseId, item.iiclCode(), item.component(),
93	                    item.description(), item.responsibility(), item.repairCost());
94	        }
95	        caseRepository.updateState(caseId, CaseStatus.SURVEYED, row.determination(), LocalDateTime.now(clock));
96	        CaseDetailView view = detail(caseId);
97	        idempotency.completeInTransaction(request.requestId(), view);
98	        return view;
99	    }
100	
101	    /**
102	     * 估价：生成新估价版本，旧版本置 SUPERSEDED；单项修理费超箱值 30% 判全损。
103	     * 批复逾期后须重新估价；批复仍在有效期内时拒绝重复估价。
104	     */
105	    @Transactional
106	    public EstimateView estimate(long caseId, EstimateRequest request) {
107	        CaseRow row = lockCase(caseId);
108	        if (row.status() == CaseStatus.APPROVED) {
109	            ApprovalView active = flowRepository.findActiveApproval(caseId);
110	            LocalDate today = LocalDate.now(clock);
111	            if (active != null && !today.isAfter(active.approvalDate().plusDays(APPROVAL_VALID_DAYS - 1))) {
112	                throw ApiException.conflict("修理批复仍在有效期内，无需重新估价");
113	            }
114	        } else if (row.status() != CaseStatus.SURVEYED && row.status() != CaseStatus.ESTIMATED) {
115	            throw ApiException.conflict("当前状态不允许估价: " + row.status());
116	        }
117	        if (row.status() == CaseStatus.ESTIMATED) {
118	            // 询价/开标进行中固定残损项集合与全损判定，禁止重新估价；零有效报价（NO_AWARD）后允许
119	            if (inquiryRepository.hasOpenOrOpenedInquiry(caseId)) {
120	                throw ApiException.unprocessable("密封询价进行中，残损项集合与判定已固定，不能重新估价");
121	            }
122	        }
123	        var items = flowRepository.listItems(caseId);
124	        if (items.isEmpty()) {
125	            throw ApiException.badRequest("残损清单为空，无法估价");
126	        }
127	        BigDecimal threshold = row.containerValue().multiply(TOTAL_LOSS_THRESHOLD);
128	        BigDecimal total = items.stream()
129	                .map(item -> item.repairCost())
130	                .reduce(BigDecimal.ZERO, BigDecimal::add);
131	        Determination determination = items.stream()
132	                .anyMatch(item -> item.repairCost().compareTo(threshold) > 0)
133	                ? Determination.TOTAL_LOSS
134	                : Determination.REPAIR;
135	        flowRepository.supersedeActiveApprovals(caseId);
136	        long estimateId = flowRepository.insertEstimate(caseId, total, determination,
137	                request.requestId(), LocalDateTime.now(clock));
138	        caseRepository.updateState(caseId, CaseStatus.ESTIMATED, determination, LocalDateTime.now(clock));
139	        EstimateView view = flowRepository.listEstimates(caseId).stream()
140	                .filter(e -> e.id() == estimateId)
141	                .findFirst()
142	                .orElseThrow();
143	        idempotency.completeInTransaction(request.requestId(), view);
144	        return view;
145	    }
146	
147	    /** 修理批复：仅修理判定可批复，全损与修理不得并发成立 */
148	    @Transactional
149	    public ApprovalView approve(long caseId, ApprovalRequest request) {
150	        CaseRow row = lockCase(caseId);
151	        requireStatus(row, CaseStatus.ESTIMATED, "仅已估价状态可批复修理");
152	        if (row.determination() != Determination.REPAIR) {
153	            throw ApiException.conflict("全损案件不得批复修理，判定唯一");
154	        }
155	        // 询价投标/开标进行中必须经密封比价，旧批复入口不得绕过；零有效报价（NO_AWARD）后旧入口兼容
156	        if (inquiryRepository.hasOpenOrOpenedInquiry(caseId)) {
157	            throw ApiException.unprocessable("密封询价进行中，须经开标比价与双重复核批复，不能直接批复");
158	        }
159	        EstimateView current = flowRepository.findCurrentEstimate(caseId);
160	        if (current == null) {
161	            throw ApiException.conflict("无有效估价版本，无法批复");
162	        }
163	        LocalDate approvalDate = request.approvalDate() != null ? request.approvalDate() : LocalDate.now(clock);
164	        long approvalId = flowRepository.insertApproval(caseId, current.id(), approvalDate, LocalDateTime.now(clock));
165	        caseRepository.updateState(caseId, CaseStatus.APPROVED, row.determination(), LocalDateTime.now(clock));
166	        ApprovalView view = flowRepository.listApprovals(caseId).stream()
167	                .filter(a -> a.id() == approvalId)
168	                .findFirst()
169	                .orElseThrow();
170	        idempotency.completeInTransaction(request.requestId(), view);
171	        return view;
172	    }
173	
174	    /** 修理（或返修）完工：完工日期须在批复 7 个 UTC 自然日有效期内，恰第 7 日有效 */
175	    @Transactional
176	    public CompletionView completeRepair(long caseId, CompletionRequest request) {
177	        CaseRow row = lockCase(caseId);
178	        if (row.status() != CaseStatus.APPROVED && row.status() != CaseStatus.REWORK) {
179	            throw ApiException.conflict("当前状态不允许登记完工: " + row.status());
180	        }
181	        ApprovalView active = flowRepository.findActiveApproval(caseId);
182	        if (active == null) {
183	            throw ApiException.conflict("无有效修理批复，无法登记完工");
184	        }
185	        LocalDate completionDate = request.completionDate() != null ? request.completionDate() : LocalDate.now(clock);
186	        LocalDate lastValidDay = active.approvalDate().plusDays(APPROVAL_VALID_DAYS - 1);
187	        if (completionDate.isAfter(lastValidDay)) {
188	            throw ApiException.conflict("修理批复已逾期（有效期 7 个自然日），须重新估价");
189	        }
190	        boolean rework = row.status() == CaseStatus.REWORK;
191	        flowRepository.insertCompletion(caseId, completionDate, rework, LocalDateTime.now(clock));
192	        caseRepository.updateState(caseId, CaseStatus.REPAIR_DONE, row.determination(),
193	                row.reworkCount(), LocalDateTime.now(clock));
194	        CompletionView view = flowRepository.listCompletions(caseId).stream()
195	                .reduce((first, second) -> second)
196	                .orElseThrow();
197	        idempotency.completeInTransaction(request.requestId(), view);
198	        return view;
199	    }
200	
201	    /** 复检：不合格仅允许返修一次，返修后仍不合格转全损评估 */
202	    @Transactional
203	    public CaseView reinspect(long caseId, ReinspectionRequest request) {
204	        CaseRow row = lockCase(caseId);
205	        requireStatus(row, CaseStatus.REPAIR_DONE, "仅修理完工后可复检");
206	        flowRepository.insertReinspection(caseId, request.passed(), LocalDateTime.now(clock));
207	        LocalDateTime now = LocalDateTime.now(clock);
208	        if (request.passed()) {
209	            caseRepository.updateState(caseId, CaseStatus.REPAIR_PASSED, row.determination(),
210	                    row.reworkCount(), now);
211	        } else if (row.reworkCount() == 0) {
212	            caseRepository.updateState(caseId, CaseStatus.REWORK, row.determination(), 1, now);
213	        } else {
214	            flowRepository.supersedeActiveApprovals(caseId);
215	            caseRepository.updateState(caseId, CaseStatus.TOTAL_LOSS_PENDING, Determination.TOTAL_LOSS,
216	                    row.reworkCount(), now);
217	        }
218	        CaseView view = loadCase(caseId).toView();
219	        idempotency.completeInTransaction(request.requestId(), view);
220	        return view;
221	    }
222	
223	    /**
224	     * 结案：修理放行与案件关闭在同一事务内完成；结案为终态，重复结案返回幂等成功。
225	     */
226	    @Transactional
227	    public CaseView close(long caseId, CloseRequest request) {
228	        CaseRow row = lockCase(caseId);
229	        LocalDateTime now = LocalDateTime.now(clock);
230	        if (TERMINAL.contains(row.status())) {
231	            CaseView view = row.toView();
232	            idempotency.completeInTransaction(request.requestId(), view);
233	            return view;
234	        }
235	        if (row.status() == CaseStatus.REPAIR_PASSED) {
236	            caseRepository.close(caseId, CaseStatus.RELEASED, now);
237	        } else if (row.determination() == Determination.TOTAL_LOSS
238	                && (row.status() == CaseStatus.ESTIMATED || row.status() == CaseStatus.TOTAL_LOSS_PENDING)) {
239	            caseRepository.close(caseId, CaseStatus.TOTAL_LOSS, now);
240	        } else {
241	            throw ApiException.conflict("当前状态不允许结案: " + row.status());
242	        }
243	        CaseView view = loadCase(caseId).toView();
244	        idempotency.completeInTransaction(request.requestId(), view);
245	        return view;
246	    }
247	
248	    /** 检验照片：结案后迟到照片只记迟到事件，不改变案件状态 */
249	    @Transactional
250	    public PhotoResult photo(long caseId, PhotoRequest request) {
251	        CaseRow row = lockCase(caseId);
252	        LocalDateTime now = LocalDateTime.now(clock);
253	        if (TERMINAL.contains(row.status())) {
254	            flowRepository.insertEvent(caseId, "LATE_PHOTO", request.photoRef(), now);
255	            return new PhotoResult("LATE_RECORDED");
256	        }
257	        flowRepository.insertEvent(caseId, "PHOTO", request.photoRef(), now);
258	        return new PhotoResult("ATTACHED");
259	    }
260	
261	    /** 案件全量明细：残损清单、估价版本与修理链均可复算 */
262	    @Transactional(readOnly = true)
263	    public CaseDetailView detail(long caseId) {
264	        CaseRow row = caseRepository.findById(caseId)
265	                .orElseThrow(() -> ApiException.notFound("残损案不存在: " + caseId));
266	        return new CaseDetailView(
267	                row.toView(),
268	                flowRepository.listItems(caseId),
269	                flowRepository.listEstimates(caseId),
270	                flowRepository.listApprovals(caseId),
271	                flowRepository.listCompletions(caseId),
272	                flowRepository.listReinspections(caseId),
273	                flowRepository.listEvents(caseId));
274	    }
275	
276	    private CaseRow lockCase(long caseId) {
277	        return caseRepository.findByIdForUpdate(caseId)
278	                .orElseThrow(() -> ApiException.notFound("残损案不存在: " + caseId));
279	    }
280	
281	    private CaseRow loadCase(long caseId) {
282	        return caseRepository.findById(caseId)
283	                .orElseThrow(() -> ApiException.notFound("残损案不存在: " + caseId));
284	    }
285	
286	    private void requireStatus(CaseRow row, CaseStatus expected, String message) {
287	        if (row.status() != expected) {
288	            throw ApiException.conflict(message + "，当前状态: " + row.status());
289	        }
290	    }
291	}
