94	    // ---- 构造辅助 ----
95	
96	    private long repairCaseWithTwoItems(String containerNo) {
97	        long caseId = caseService.register(new RegisterRequest(
98	                "reg-" + UUID.randomUUID(), containerNo, new BigDecimal("10000.00"))).id();
99	        caseService.survey(caseId, new SurveyRequest("svy-" + UUID.randomUUID(), List.of(
100	                new DamageItemInput("DN", "侧板", "凹痕", Responsibility.OWNER, new BigDecimal("1000.00")),
101	                new DamageItemInput("BR", "底梁", "弯曲", Responsibility.TERMINAL, new BigDecimal("500.00")))));
102	        caseService.estimate(caseId, new EstimateRequest("est-" + UUID.randomUUID()));
103	        return caseId;
104	    }
