110	    private long publish(long caseId, String requestId, int expectedVersion) {
111	        List<Long> items = itemIds(caseId);
112	        return inquiryService.publishInquiry(caseId, new PublishInquiryRequest(
113	                requestId, expectedVersion, DEADLINE, List.of(
114	                        new InquiryItemSpec(items.get(0), List.of("WELD", "STRAIGHTEN")),
115	                        new InquiryItemSpec(items.get(1), List.of("WELD", "REPLACE"))))).id();
116	    }
