118	    private void supplier(String no, List<String> methods) {
119	        inquiryService.createSupplier(new CreateSupplierRequest(
120	                "csup-" + UUID.randomUUID(), no, "供应商-" + no, methods));
121	        inquiryService.grantQualification(no, new QualificationGrantRequest(
122	                "q-" + UUID.randomUUID(), 0, T0.minus(Duration.ofDays(30)), null));
