137	    // ---- 主流程 ----
138	
139	    @Test
140	    void sealedBiddingLowestTotalWinsAndTwoReviewersConvertToApproval() {
141	        long caseId = repairCaseWithTwoItems("TEMU3000001");
142	        long inquiryId = publish(caseId, "pub-1", 0);
143	        supplier("S001", List.of("WELD"));
144	        supplier("S002", List.of("STRAIGHTEN", "REPLACE"));
145	
146	        InquiryView inquiry = inquiryService.getInquiry(inquiryId);
147	        assertThat(inquiry.version()).isEqualTo(1);
148	        assertThat(inquiry.status().name()).isEqualTo("OPEN");
149	        assertThat(inquiry.items()).hasSize(2);
150	        assertThat(inquiry.items().get(0).allowedMethods()).containsExactly("STRAIGHTEN", "WELD");
151	
152	        bid(inquiryId, "S001", 0, "WELD", 1000, "WELD", 2000, "bid-s1-1"); // 3000
153	        bid(inquiryId, "S002", 0, "STRAIGHTEN", 1500, "REPLACE", 1400, "bid-s2-1"); // 2900
154	
155	        clock.set(AFTER_DEADLINE);
156	        OpeningView opening = open(inquiryId, 1, "open-1");
157	
158	        assertThat(opening.status()).isEqualTo("AWARDED");
159	        assertThat(opening.winnerSupplierNo()).isEqualTo("S002");
160	        assertThat(opening.winnerTotalCents()).isEqualTo(2900);
161	        assertThat(opening.entries()).hasSize(2);
162	        OpeningEntryView s1 = opening.entries().stream().filter(e -> e.supplierNo().equals("S001")).findFirst().orElseThrow();
163	        OpeningEntryView s2 = opening.entries().stream().filter(e -> e.supplierNo().equals("S002")).findFirst().orElseThrow();
164	        assertThat(s1.valid()).isTrue();
165	        assertThat(s1.rankNo()).isEqualTo(2);
166	        assertThat(s2.valid()).isTrue();
167	        assertThat(s2.rankNo()).isEqualTo(1);
168	        assertThat(s2.qualificationVersion()).isEqualTo(1);
