170	        // 开标后询价版本 +1，报价冻结
171	        assertThat(inquiryService.getInquiry(inquiryId).version()).isEqualTo(2);
172	        assertThat(inquiryService.getInquiry(inquiryId).status().name()).isEqualTo("OPENED");
173	
174	        // 第一名复核不转批复
175	        ReviewResultView first = inquiryService.review(inquiryId, new ReviewRequest("rv-" + UUID.randomUUID(), "alice"));
176	        assertThat(first.opening().converted()).isFalse();
177	        assertThat(first.approvalDate()).isNull();
178	        assertThat(caseService.detail(caseId).caseInfo().status()).isEqualTo(CaseStatus.ESTIMATED);
179	
180	        // 第二名不同复核人齐 → 转批复
181	        ReviewResultView second = inquiryService.review(inquiryId, new ReviewRequest("rv-" + UUID.randomUUID(), "bob"));
182	        assertThat(second.opening().converted()).isTrue();
183	        assertThat(second.approvalDate()).isEqualTo(java.time.LocalDate.parse("2026-09-21"));
184	
185	        CaseDetailView detail = caseService.detail(caseId);
186	        assertThat(detail.caseInfo().status()).isEqualTo(CaseStatus.APPROVED);
187	        assertThat(detail.caseInfo().determination()).isEqualTo(Determination.REPAIR);
188	        assertThat(detail.approvals()).hasSize(1);
189	        assertThat(detail.approvals().get(0).source()).isEqualTo("INQUIRY");
190	        assertThat(detail.approvals().get(0).openingId()).isEqualTo(opening.id());
191	        assertThat(inquiryService.getInquiry(inquiryId).status().name()).isEqualTo("CONVERTED");
192	        assertThat(inquiryService.getInquiry(inquiryId).version()).isEqualTo(3);
193	        assertThat(inquiryService.getBid(inquiryId, "S002").status()).isEqualTo("FROZEN");
194	    }
