198	    @Test
199	    void bidBeforeDeadlineAllowedExactlyAtDeadlineRejected() {
200	        long caseId = repairCaseWithTwoItems("TEMU3000002");
201	        long inquiryId = publish(caseId, "pub-2", 0);
202	        supplier("S100", List.of("WELD"));
203	
204	        // now == 截止时刻：拒绝
205	        clock.set(DEADLINE);
206	        assertThatThrownBy(() -> bid(inquiryId, "S100", 0, "WELD", 100, "WELD", 200, "bid-edge"))
207	                .isInstanceOf(ApiException.class)
208	                .satisfies(e -> assertThat(((ApiException) e).status()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY))
209	                .hasMessageContaining("截止");
210	
211	        // 截止前一刻：允许
212	        clock.set(DEADLINE.minus(Duration.ofNanos(1)));
213	        BidView view = bid(inquiryId, "S100", 0, "WELD", 100, "WELD", 200, "bid-edge-ok");
214	        assertThat(view.currentVersion()).isEqualTo(1);
215	    }
