220	        long inquiryId = publish(caseId, "pub-3", 0);
221	        supplier("S101", List.of("WELD"));
222	        bid(inquiryId, "S101", 0, "WELD", 100, "WELD", 200, "b1");
223	        // 默认 T0 仍早于截止
224	        assertThatThrownBy(() -> open(inquiryId, 1, "open-early"))
225	                .isInstanceOf(ApiException.class)
226	                .satisfies(e -> assertThat(((ApiException) e).status()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY));
