207	    @Test
208	    void openingAndRevocationRaceIsConsistent() throws Exception {
209	        long inquiryId = setupCaseWithInquiryAndSupplier("TEMU5000003", "C003",
210	                List.of("WELD", "STRAIGHTEN", "REPLACE"));
211	        inquiryService.submitBid(inquiryId, "C003", validBid("b-" + UUID.randomUUID(), 0, "WELD", "REPLACE"));
212	        Instant revokeAt = DEADLINE.plusSeconds(30);
213	        clock.set(revokeAt);
214	
215	        // 开标与撤销同时发起，反复制造锁竞争
216	        int openThreads = 5;
217	        int total = openThreads + 1;
218	        CountDownLatch ready = new CountDownLatch(total);
219	        CountDownLatch start = new CountDownLatch(1);
220	        List<Future<Object>> futures = new ArrayList<>();
